with with_windows as (select *, sum(stock_qty) over (partition by category order by stock_qty, id rows between unbounded preceding and current row) cumulative_stock_qty, corr(cost, price) over (partition by supplier_id) corr_cost_price from products), eligible as (select s.* from with_windows s where not exists (select 1 from inventory c where c.product_id = s.id and c.last_restock < s.launch_date)), matched_keys as (select supplier_id from eligible except all select supplier_id from products where category <> 'Books'), reconciled as (select s.* from eligible s inner join matched_keys k on s.supplier_id = k.supplier_id), cleaned as (select *, sort_array(tags) sorted_tags, upper(brand) brand_upper, coalesce(brand, 'OTHER') resolved_brand from reconciled where launch_date > date '2023-09-10' and brand is not null), joined as (select a.*, p.supplier_name, p.city from cleaned a inner join suppliers p on a.supplier_id <=> p.id) select supplier_id, count(case when category = 'Books' then 1 end) as books_count, sum(case when brand = 'Umbrella' then corr_cost_price else 0 end) as umbrella_corr_cost_price, count_if(city = 'London') as london_events from joined group by supplier_id order by books_count
